pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 _value) public {
        vm.assume(_value < 10 ether);
        address caller = address(0x1234);
        vm.deal(caller, _value);
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: _value}("");
        assertTrue(!ok);
    }
}
